def(
  "삼각비",
  "03",
  "한 삼각비의 값을 알 때 다른 삼각비의 값 구하기",
  SEC.뜻,
  "응용",
  (rng) =>
    attempt(120, () => {
      // 세 쌍을 **기약으로** 줄인다 — 안 그러면 발문의 `tan A=3/4` 와 해설의
      // 「밑변 16, 높이 12」가 따로 논다(같은 값인데 학생은 딴 삼각형으로 읽는다).
      const [p0, q0, r0] = pick(rng, TRIPLES);
      const g0 = gcd(gcd(p0, q0), r0);
      const [p, q, r] = [p0 / g0, q0 / g0, r0 / g0];
      const given = intBetween(rng, 0, 2);
      const want = intBetween(rng, 0, 2);
      if (given === want) return null;
      // $\tan$ 은 «대변/이웃변»이라 진분수가 아니면 지면에서 대분수가 된다.
      if ((given === 2 || want === 2) && p >= q) return null;
      const pair = (fn: number): [number, number] =>
        fn === 0 ? red(p, r) : fn === 1 ? red(q, r) : red(p, q);
      const [gn, gd] = pair(given);
      const [wn, wd] = pair(want);
      const legText =
        given === 0
          ? `빗변의 길이가 $${r}$, 높이가 $${p}$인 직각삼각형에서 밑변의 길이는 $\\sqrt{${r}^2-${p}^2}=${q}$`
          : given === 1
            ? `빗변의 길이가 $${r}$, 밑변의 길이가 $${q}$인 직각삼각형에서 높이는 $\\sqrt{${r}^2-${q}^2}=${p}$`
            : `밑변의 길이가 $${q}$, 높이가 $${p}$인 직각삼각형에서 빗변의 길이는 $\\sqrt{${p}^2+${q}^2}=${r}$`;
      return {
        content: `$0^\\circ<A<90^\\circ$인 $\\angle A$에 대하여 $${trigOf(given, "A")}=${frac(gn, gd)}$일 때, $${trigOf(want, "A")}$의 값을 구하시오.`,
        answer: `$${frac(wn, wd)}$`,
        solution: `$${trigOf(given, "A")}=${frac(gn, gd)}$이므로 ${legText}이다.\n따라서 $${trigOf(want, "A")}=${frac(wn, wd)}$이다.`,
        facts: { p, q, r, given, want, gnum: gn, gden: gd, num: wn, den: wd },
        figureSpec: null,
      };
    }),
),
